import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 125, qty: 2 }]), 250);
});

test('bulk discount starts at 2 lines', () => {
  assert.equal(total([{ price: 1000, qty: 5 }]), 5000); // 1 line: no bulk discount
  assert.equal(total([{ price: 1000, qty: 1 }, { price: 1000, qty: 1 }]), 1900); // 2000 * 0.95
  assert.equal(total([{ price: 1000, qty: 1 }, { price: 1000, qty: 1 }], 0.1), 1710); // 2000 * 0.9 * 0.95
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});

test('bulk discount rounds the half yen up', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 11, qty: 1 }));
  assert.equal(total(lines), 105); // 110 * 0.95 = 104.5
});

test('customer discount is applied once', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('bulk discount is applied once, after the customer discount', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(lines, 0.1), 8550); // 10000 * 0.9 * 0.95
});
